struct Control{using DrainFn=Event::DrainResult(*)(void*,std::size_t) noexcept;void* Runtime{};DrainFn Drain{};}; struct Loop{Control* C{};void operator()(Threading::ThreadContext& ctx) noexcept{while(!ctx.IsStopRequested()){if(C&&C->Runtime&&C->Drain){auto d=C->Drain(C->Runtime,8U);if(d.WorkRemaining)continue;}if(ctx.Wait()!=Threading::ThreadWaitResult::Woken)return;}}};
