template<class R>Event::DrainResult Drain(void* p,std::size_t n) noexcept{return static_cast<R*>(p)->template Drain<ListenerThread>(n);} enum class TransportResult:std::uint8_t{Accepted}; struct FakeTransport{std::atomic<unsigned> Calls{0};std::atomic<std::int32_t> Last{0};TransportResult operator()(const BoundaryEvent& e) noexcept{Last.store(e.Value,std::memory_order_relaxed);Calls.fetch_add(1,std::memory_order_relaxed);return TransportResult::Accepted;}};
int Run(){MemoryResourceProvider resource;MutexProvider mm;Allocator alloc;MemoryRuntime memory(mm,alloc,resource);Memory::MemoryTopologyInitializationFailure mf{};if(memory.Initialize(mf)!=Memory::MemoryTopologyInitializationResult::Succeeded)return 1;Control control{};auto bindings=std::make_tuple(Threading::BindDedicatedThread<ListenerThread>(Loop{&control}));using Bindings=decltype(bindings);using TR=Threading::StaticThreadingRuntime<ThreadingTopology,Bindings,SignalProvider,ExecutionContextProvider,SpinLockProvider,MutexProvider>;static TR threading(std::move(bindings));if(threading.Initialize()!=Threading::ThreadingInitializationResult::Succeeded||threading.Start()!=Threading::ThreadingStartResult::Succeeded)return 2;EventMutex em;Handler handler;using EB=Event::Bootstrap<Architecture,EventPlan,MemoryRuntime,TR>;EB bootstrap(memory,threading,em,handler);if(bootstrap.Initialize()!=Event::InitializationResult::Initialized)return 3;auto& events=bootstrap.RuntimeInstance();using ER=std::remove_reference_t<decltype(events)>;control.Runtime=&events;control.Drain=&Drain<ER>;if(events.Subscribe<ListenerThread,BoundaryEvent>()!=Event::SubscribeResult::Subscribed)return 4;auto listener=threading.ThreadHandle<ListenerThread>();if(listener.Start()!=Threading::ThreadStartResult::Started)return 5;FakeTransport transport;BoundaryEvent event{77};auto both=events.Dispatch(Event::LocalAndRemote{},event,Event::UntilHandoff{},transport);if(both.Local()!=Event::DispatchResult::Accepted||!both.Remote().WasAttempted()||both.Remote().Result()!=TransportResult::Accepted||transport.Calls.load()!=1||transport.Last.load()!=77)return 6;for(std::size_t i=0;i<200000U&&handler.Count.load(std::memory_order_acquire)==0U;++i)ExecutionContextProvider::Yield();if(handler.Count.load()!=1||handler.Last.load()!=77)return 7;auto remoteOnly=Event::DispatchScoped(Event::RemoteOnly{},BoundaryEvent{88},Event::UntilHandoff{},transport);if(!remoteOnly.WasAttempted()||transport.Calls.load()!=2||transport.Last.load()!=88)return 8;if(events.Ingress(BoundaryEvent{99})!=Event::DispatchResult::Accepted)return 9;for(std::size_t i=0;i<200000U&&handler.Count.load(std::memory_order_acquire)<2U;++i)ExecutionContextProvider::Yield();if(handler.Count.load()!=2||handler.Last.load()!=99)return 10;if(listener.RequestStop()!=Threading::ThreadStopRequestResult::Accepted)return 11;while(listener.State()==Threading::ThreadState::Running)ExecutionContextProvider::Yield();if(threading.BeginShutdown()!=Threading::ThreadingShutdownResult::Accepted)return 12;while(!threading.IsExecutionQuiescent())ExecutionContextProvider::Yield();if(threading.FinalizeShutdown()!=Threading::ThreadingFinalizationResult::Completed)return 13;if(memory.TearDown()!=Memory::MemoryTopologyTeardownResult::Succeeded)return 14;std::printf("EDP-Event transport-boundary: PASS\n");return 0;}
